const now = new Date();
return [{json:{
 executionId:`pk-real-estate-${now.toISOString()}-${Math.random().toString(36).slice(2,8)}`,
 country:'Pakistan', countryCode:'PK', locale:'en-PK', language:'English',
 cities:[
  {city:'Karachi',province:'Sindh'},{city:'Lahore',province:'Punjab'},{city:'Islamabad',province:'Islamabad Capital Territory'},
  {city:'Rawalpindi',province:'Punjab'},{city:'Faisalabad',province:'Punjab'},{city:'Multan',province:'Punjab'},
  {city:'Peshawar',province:'Khyber Pakhtunkhwa'},{city:'Quetta',province:'Balochistan'},
  {city:'Gujranwala',province:'Punjab'},{city:'Sialkot',province:'Punjab'},{city:'Hyderabad',province:'Sindh'},
  {city:'Bahawalpur',province:'Punjab'},{city:'Abbottabad',province:'Khyber Pakhtunkhwa'}
 ],
 niche:'Real Estate',
 keywords:['real estate agency','property dealer','property developer','real estate developer','commercial real estate','property management company','housing society','real estate investment company','estate agent','property consultant'],
 limits:{keywordsPerRun:12,maxResultsPerKeyword:50,crawlPagesPerSite:6,requestDelayMs:900},
 scraper:{baseUrl:'http://localhost:3000'},
 deepseek:{apiKey:'PASTE_DEEPSEEK_API_KEY_HERE',apiUrl:'https://api.deepseek.com/chat/completions',model:'deepseek-chat'}
}}];

const cfg=$input.first().json; const state=$getWorkflowStaticData('global'); state.cursor=Number(state.cursor||0);
const candidates=cfg.cities.flatMap(m=>cfg.keywords.map(k=>({...m,keyword:`${k} in ${m.city}, Pakistan`,category:k})));
const count=Math.min(Number(cfg.limits.keywordsPerRun||12),candidates.length); const out=[];
for(let i=0;i<count;i++){const c=candidates[(state.cursor+i)%candidates.length];out.push({json:{...cfg,...c,industry:cfg.niche}})}
state.cursor=(state.cursor+count)%candidates.length; return out;

const out=[]; for(const item of $input.all()){const j=item.json;let response;
try{response=await this.helpers.httpRequest({method:'POST',url:`${j.scraper.baseUrl}/api/scrape/search`,headers:{'Content-Type':'application/json'},body:{query:j.keyword,maxResults:j.limits.maxResultsPerKeyword},json:true,timeout:120000})}catch(e){console.log(`Scrape failed for ${j.keyword}: ${e.message}`);continue}
for(const p of response?.data?.results||[]){if(!p.title)continue;let domain='';try{domain=new URL(p.website).hostname.replace(/^www\./,'').toLowerCase()}catch{}
out.push({json:{...j,businessName:p.title,address:p.address||'',phone:p.phone||'',website:p.website||'',domain,googleMapsUrl:p.url||p.googleMapsUrl||'',latitude:p.latitude??null,longitude:p.longitude??null,rating:Number(p.rating)||null,reviews:Number(String(p.reviews||'').replace(/[^0-9]/g,''))||0,rawCategory:p.category||j.category,sourceRetrievedAt:new Date().toISOString()}})}} return out;

function text(html){return String(html||'').replace(/<script[\s\S]*?<\/script>/gi,' ').replace(/<style[\s\S]*?<\/style>/gi,' ').replace(/<[^>]+>/g,' ').replace(/&[a-z]+;/gi,' ').replace(/\s+/g,' ').trim()}
function uniq(a){return [...new Set(a.filter(Boolean))]}; const out=[];
for(const item of $input.all()){const j=item.json;const pages=[];if(j.website){const base=j.website.replace(/\/$/,'');for(const path of ['','/about','/about-us','/team','/leadership','/contact']){if(pages.length>=j.limits.crawlPagesPerSite)break;const url=base+path;try{const html=await this.helpers.httpRequest({url,method:'GET',timeout:15000,headers:{'User-Agent':'SRLINES Pakistan real-estate research bot'},json:false});pages.push({url,html:String(html)})}catch{}}}
const combined=pages.map(p=>p.html).join(' ');const emails=uniq((combined.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi)||[]).map(e=>e.toLowerCase()));
const linkedin=uniq((combined.match(/https?:\/\/(?:[a-z]+\.)?linkedin\.com\/(?:in|company)\/[A-Za-z0-9_%?&=./-]+/gi)||[]));
const socials={linkedin,facebook:uniq(combined.match(/https?:\/\/(?:www\.)?facebook\.com\/[A-Za-z0-9_.?&=/-]+/gi)||[]),instagram:uniq(combined.match(/https?:\/\/(?:www\.)?instagram\.com\/[A-Za-z0-9_.?&=/-]+/gi)||[])};
const snippets=text(combined).slice(0,18000);out.push({json:{...j,emails,socialProfiles:socials,websiteText:snippets,websiteSignals:{hasWebsite:!!j.website,emailCount:emails.length,linkedinCount:linkedin.length,pagesCrawled:pages.map(p=>p.url)},contacts:[]}})} return out;

function fallback(j){let s=20;if(j.website)s+=15;if(j.emails.length)s+=15;if(j.socialProfiles.linkedin.length)s+=10;if(j.reviews>=50)s+=10;if(j.reviews>=200)s+=10;if(j.rating>=4)s+=10;return Math.min(100,s)}
const cfg=$('Pakistan Runtime Config').first().json;const out=[];for(const item of $input.all()){const j=item.json;const base=fallback(j);let ai={score:base,grade:base>=80?'A':base>=65?'B':base>=45?'C':'D',qualification:'Heuristic score; AI was unavailable.',nurture_strategy:'Research and verify a senior decision-maker before outreach.',contacts:[]};
try{if(!cfg.deepseek.apiKey||cfg.deepseek.apiKey.startsWith('PASTE_'))throw new Error('DeepSeek key is not configured');const prompt=`Research/qualification task only; do not write or send outreach. Using the supplied public website evidence for a Pakistan real-estate business, return JSON: score (0-100), grade (A/B/C/D), qualification, nurture_strategy, and contacts array. Each contact must contain full_name, job_title, authority_level (owner/c-suite/director/manager/unknown), email, phone, linkedin_url, source_url, confidence (0-100), is_decision_maker. Never invent a person or contact detail; omit unsupported fields. Prioritize CEO, founder, owner, managing director, director, partner and head of sales. Lead: ${JSON.stringify({business:j.businessName,city:j.city,category:j.rawCategory,rating:j.rating,reviews:j.reviews,emails:j.emails,socialProfiles:j.socialProfiles,website:j.website,websiteText:j.websiteText.slice(0,12000)})}`;
const r=await this.helpers.httpRequest({method:'POST',url:cfg.deepseek.apiUrl,headers:{Authorization:`Bearer ${cfg.deepseek.apiKey}`,'Content-Type':'application/json'},body:{model:cfg.deepseek.model,temperature:0.1,messages:[{role:'user',content:prompt}],response_format:{type:'json_object'}},json:true,timeout:120000});ai={...ai,...JSON.parse(r.choices?.[0]?.message?.content||'{}')}}catch(e){ai.error=e.message}
const score=Math.max(0,Math.min(100,Math.round(Number(ai.score)||base)));out.push({json:{...j,score,grade:ai.grade||'D',qualification:ai.qualification||'',nurtureStrategy:ai.nurture_strategy||'',contacts:Array.isArray(ai.contacts)?ai.contacts:[],aiAnalysis:ai}})}return out;
